effect.shader:
float sdRoundedBox(vec2 p, vec2 b, float r) {
vec2 q = abs(p) - b + r;
return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - r;
}
void main() {
vec2 uv = acLayerNorm;
vec2 p = uv - 0.5 - vec2(offsetX, offsetY) * 0.5;
float aspect = acLayerSize.x / acLayerSize.y;
p.x *= aspect;
vec2 halfExtents = vec2(0.5 * scaleX * aspect, 0.5 * scaleY);
float r = radius * min(halfExtents.x, halfExtents.y);
float dist = sdRoundedBox(p, halfExtents - r, r);
float featherSize = feather * min(halfExtents.x, halfExtents.y) * 0.5;
featherSize = max(featherSize, 0.0001);
float mask = 1.0 - smoothstep(-featherSize, featherSize, dist);
if (invert) mask = 1.0 - mask;
mask *= opacity;
vec4 col = texture2DCv(inputImg.texture, acScreenNorm);
gl_FragColor = vec4(col.rgb * mask, col.a * mask);
}
